#!/bin/sh
# 🔗️ The second chain of closing runs, again ONE request in the capacity queue at a time: chain2.sh
# Waits for the first chain to end (f-cmd-estimate.log), then: the share of the evaluation in one resolve and a fresh run of the generator on the rigid reference asset (800 MB), the two halves of the suite that tell which tests make its worker grow (3200 MB each), the type check (3200 MB).
# Do not edit this file while it runs.
set -u
R=/Users/ueli/Documents/semio
S="$R/🎓️teaching/🏛️architecture/🧍️staffage"
T="$S/🧪️tests/🔭️multiview-coverage"
U="$R/.🧬semio/🦑️repo/🎫️tickets/🎆️26/🌙️11/☀️22/GET-STAFFAGE-RUNNING-END-TO-END-AND-FINISH-ALL-STAFFAGE-TICKETS"
M="$U/🧰️matrix/MM"
G="$U/🗑️generated/matrix/MM"
BUN=$(ls ~/Library/Caches/semio/runtimes/bun/*/bun | head -1)
VITEST="'$BUN' node_modules/vitest/vitest.mjs run --configLoader native --reporter=verbose --config '$S/🧪️tests/🎚️config/🟦️.ts' '🔭️multiview-coverage'"
cd "$R" || exit 1
until grep -q "^guarded:" "$G/f-cmd-estimate.log" 2>/dev/null; do sleep 5; done
CMD="'$BUN' '$M/split.ts' jogger 50 saguaro-cactus 50 saguaro-cactus 100 finned-heat-exchanger 50" sh "$M/final.sh" 800 cmd:split
CMD="'$BUN' '$T/📊️matrix.ts' --language en --out '$G/f-rigid' --jobs 1 --fresh --assets finned-heat-exchanger" sh "$M/final.sh" 800 cmd:rigid
CMD="$VITEST -t 'authors. gate|generator records'" sh "$M/final.sh" 3200 cmd:suite-gate
CMD="$VITEST -t 'derived-view detection|analysis cue|anchor landmarks'" sh "$M/final.sh" 3200 cmd:suite-derived
CMD="'$BUN' node_modules/typescript/bin/tsc --noEmit -p '$S/📦️packages/🟦️typescript/tsconfig.json'" sh "$M/final.sh" 3200 cmd:tsc
echo "chain2 ended"
